const PORTION = 10; // Kanäle je Portion (talents_plattform_abruf_liste p_anzahl)
// Lauf starten (Stefan 18.10.2026): Portionen der fälligen Kanäle nacheinander abarbeiten (talents_abruf_liste mit p_anzahl).
// erledigt = in diesem Lauf schon bearbeitete Kanäle (auch mit Fehler), damit sie nicht erneut drankommen.
// Sofortabruf (Stefan 19.10.2026): Aufruf aus ALLY 16 über "Sofort (Einladung)" mit kanal_id und erstabruf -> nur dieser Kanal
// (Liste mit Kanal-Filter, Migration 52; erstabruf = bis 30 Tage zurück). Der nächtliche Lauf bleibt unverändert.
const sofort = $('Sofort (Einladung)').isExecuted ? ($('Sofort (Einladung)').first().json || {}) : null;
if (sofort) {
  const kanal_id = Number(sofort.kanal_id);
  if (!(Number.isInteger(kanal_id) && kanal_id > 0)) return [];
  // Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): alle_beitraege nur vom Knopf im Talent-Profil (ALLY 20); ALLY 16 schickt es nicht (= false)
  return [{ json: { runde: 0, erledigt: [], anzahl: PORTION, kanal_id, erstabruf: sofort.erstabruf === true, alle_beitraege: sofort.alle_beitraege === true } }];
}
return [{ json: { runde: 0, erledigt: [], anzahl: PORTION } }];

const PL = 'facebook';
const API = /^https:\/\/graph\.facebook\.com\/v[0-9]{1,3}\.[0-9]{1,2}$/;
// Kanäle vorbereiten (Stefan 18.10.2026, Vertrag Migration 48, 3.2): fällige Kanäle aus talents_plattform_abruf_liste OHNE Schlüssel weitergeben.
// Schlüssel und App-Geheimcodes liest nur "Zugang erneuern" bzw. "Plattform-Abruf" direkt aus "Liste holen".
// PL (Plattform) und API (erlaubte Adressen) setzt der Bau vor diesen Code.
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Talents-Abruf ' + PL + ': ' + String(r.fehler || 'Die Liste der fälligen Kanäle ist nicht lesbar.').slice(0, 200));
const lauf = $('Portion anfordern').first().json;
const erledigt = new Set((Array.isArray(lauf.erledigt) ? lauf.erledigt : []).map(Number));
const app = r.app && typeof r.app === 'object' ? r.app : {};
const TAG = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const out = [];
for (const k of Array.isArray(r.kanaele) ? r.kanaele : []) {
  const id = Number(k && k.kanal_id);
  if (!(id > 0) || erledigt.has(id)) continue;
  const j = { start: true, kanal_id: id, plattform: PL, extern_id: String(k.extern_id || ''), seite_id: String(k.seite_id || ''),
    api: String(k.api || ''), data_api: String(k.data_api || ''), von: String(k.von || ''), bis: String(k.bis || ''), tag: String(k.tag || ''),
    tage: (Array.isArray(k.tage) ? k.tage : []).filter(t => t && TAG.test(String(t.tag)) && Number(t.since) > 0 && Number(t.until) > Number(t.since))
      .map(t => ({ tag: String(t.tag), since: Number(t.since), until: Number(t.until) })),
    seit_unix: Number(k.seit_unix) > 0 ? Number(k.seit_unix) : null,
    zielgruppe_faellig: k.zielgruppe_faellig === true,
    // Migration 151 (Punkt 2j): Bildadressen laufen bald ab → vollständige Beitragsliste holen
    vorschau_auffrischen: k.vorschau_auffrischen === true,
    beitraege: (Array.isArray(k.beitraege) ? k.beitraege : []).map(b => ({ extern_id: String(b.extern_id || '') })).filter(b => /^[A-Za-z0-9_.:-]{1,100}$/.test(b.extern_id)),
    erneuern: k.erneuern === true, fehler: null };
  if (k.schluessel_fehler === true || typeof k.schluessel !== 'string' || !k.schluessel.trim()) {
    j.fehler = { code: 'schluessel', text: 'Zugangsschlüssel nicht lesbar.', abgelaufen: false };
  } else if (!/^[A-Za-z0-9_.:-]{1,100}$/.test(j.extern_id) || !API.test(j.api) || (PL === 'youtube' && j.data_api !== 'https://www.googleapis.com/youtube/v3')
             || (PL === 'facebook' && !/^[0-9]{1,30}$/.test(j.seite_id))) {
    j.fehler = { code: 'konto', text: 'Die gespeicherte Konto-ID oder API-Adresse ist ungültig. Bitte den Kanal neu verbinden.', abgelaufen: false };
  } else if (j.erneuern && app.fehler) {
    j.fehler = { code: 'app', text: String(app.fehler).slice(0, 200), abgelaufen: false };
  }
  if (j.fehler) j.erneuern = false;
  out.push({ json: j });
}
return out;

const PORTION = 10; // Kanäle je Portion (talents_plattform_abruf_liste p_anzahl)
// Nächste Portion? (Stefan 18.10.2026): weiter, solange talents_abruf_liste weitere fällige Kanäle meldet.
// Migration 195 (Stefan 01.11.2026, Abrufzeiten): die Liste vermerkt im Zeitplan-Lauf jeden ausgegebenen Kanal als Versuch (talent_abruf_versuche);
// bearbeitete Kanäle (auch mit Fehler) stehen danach nicht mehr in der Liste, die nächste Portion ist wieder PORTION groß. erledigt bleibt als Schutz.
// Ende bei App-Grenze (stopp_alle), ohne weitere Kanäle oder nach MAX_RUNDEN Portionen.
const MAX_RUNDEN = 30;
const r = $('Liste holen').first().json.r || {};
const lauf = $('Portion anfordern').first().json;
const fertig = $input.all().map(i => i.json || {});
const erledigt = Array.from(new Set((Array.isArray(lauf.erledigt) ? lauf.erledigt : []).concat(fertig.map(e => Number(e.kanal_id))).map(Number).filter(n => n > 0)));
if (fertig.some(e => e.stopp_alle === true)) return [];
if (!(Number(r.weitere) > 0)) return [];
const runde = (Number(lauf.runde) || 0) + 1;
if (runde >= MAX_RUNDEN) return [];
return [{ json: { runde, erledigt, anzahl: PORTION } }];

// ---- Fehler der Meta-APIs (Facebook-Seiten, Threads) (Stefan 18.10.2026) ----
// Fehlerobjekt error {code, message, error_subcode}; 190 = Schlüssel ungültig, 10/200–299 Rechte, 4/17/32/613/80000–80099 Grenzen
// (Rate Limiting: https://developers.facebook.com/docs/graph-api/overview/rate-limiting), 1/2/5xx vorübergehend.
const ABGELAUFEN_BEI_TOKEN = true;
function fehlerPlattform(r) {
  const status = Number(r.statusCode);
  const b = r.body && typeof r.body === 'object' ? r.body : null;
  const e = b && b.error && typeof b.error === 'object' ? b.error : null;
  if (!e && status >= 200 && status < 300 && b) return null;
  if (!e && !status) return { code: 'netz', roh: '', text: NAME + ' war nicht erreichbar.', klasse: 'temporaer' };
  if (!e) return { code: 'http' + (status || ''), roh: '', text: 'Unerwartete Antwort von ' + NAME + ' (HTTP ' + (status || '?') + ').', klasse: status === 429 ? 'grenze' : (status >= 500 ? 'temporaer' : 'sonst') };
  const code = Number(e.code);
  const roh = String(e.message || e.error_user_msg || e.type || '');
  let klasse = 'sonst';
  if (code === 190 || code === 102) klasse = 'token';
  else if (code === 10 || code === 3 || (code >= 200 && code <= 299)) klasse = 'rechte';
  else if ([4, 17, 32, 613].indexOf(code) >= 0 || (code >= 80000 && code <= 80099) || status === 429) klasse = 'grenze';
  else if (code === 1 || code === 2 || status >= 500) klasse = 'temporaer';
  return { code: isFinite(code) ? String(code) : 'graph', roh, text: NAME + ' meldet: ' + kurz(roh, 180), klasse, stopp_alle: code === 4 };
}
function kennzahl(m) {
  if (!m || typeof m !== 'object') return null;
  if (m.total_value && zahl(m.total_value.value) !== null) return zahl(m.total_value.value);
  if (Array.isArray(m.values) && m.values.length) {
    let s = null;
    for (const v of m.values) if (v && zahl(v.value) !== null) s = (s || 0) + zahl(v.value);
    return s;
  }
  return null;
}

// ---- Plattform-Modul Facebook-Seiten (Stefan 18.10.2026, Vertrag Migration 48, 1.1) ----
// Seiten-Schlüssel; Seite: GET /{page-id}?fields=followers_count,fan_count,name; Insights: /{page-id}/insights?metric=…&period=day&since&until
// (höchstens 90 Tage je Abfrage, ab 100 Likes; https://developers.facebook.com/docs/graph-api/reference/page/insights/);
// Beiträge: /{page-id}/posts (Felder laut PagePost-Referenz); Beitrags-Insights /{post-id}/insights (lifetime).
// Je Seiten-Kennzahl eine eigene Abfrage, damit eine entfallene Kennzahl (Fehler 100) die übrigen nicht verhindert.
const PL = 'facebook', NAME = 'Facebook';
const SEITE_M = { page_media_view: 'views', page_total_media_view_unique: 'reach', page_post_engagements: 'total_interactions',
  page_video_views: 'video_views', page_daily_follows_unique: 'follows' };
const POST_M = ['post_media_view', 'post_total_media_view_unique', 'post_reactions_by_type_total', 'post_clicks'];
const MAX_SEITEN = 4;
// Migration 151 (Punkt 2j): beim Auffrischen der Bildadressen alle Seiten (je 100), höchstens so viele
const MAX_SEITEN_AUFFRISCHEN = 200;
function beitragInsights(st, id) {
  st.offen.push({ art: 'beitrag', extern_id: id, pfad: id + '/insights', query: { metric: POST_M.join(',') } });
}
function beginnen(st, k) {
  const s = st.seite_id;
  // Migration 151: vollständige Liste nur mit bekanntem letzten Abruf (seit_unix); medien_komplett nur, wenn bis zum Ende durchlaufen
  st.auffrischen = k.vorschau_auffrischen === true && !!st.seit_unix; st.medien_komplett = false; st.medien_unklar = false; st.medien_ids = [];
  st.offen.push({ art: 'konto', pfad: s, query: { fields: 'followers_count,fan_count,name' } });
  if (st.tage.length) {
    for (const m of Object.keys(SEITE_M)) st.offen.push({ art: 'tag', metrik: m, pfad: s + '/insights',
      query: { metric: m, period: 'day', since: st.tage[0].since, until: st.tage[st.tage.length - 1].until } });
  }
  st.offen.push({ art: 'beitraege', seite: 1, pfad: s + '/posts', query: { fields: 'id,created_time,message,permalink_url,full_picture,status_type', limit: st.auffrischen ? 100 : 25 } });
  for (const id of st.verfolgt) beitragInsights(st, id);
}
function postWerte(body) {
  const w = {};
  for (const m of (Array.isArray(body.data) ? body.data : [])) {
    if (!m || typeof m.name !== 'string') continue;
    if (m.name === 'post_reactions_by_type_total') {
      const v = Array.isArray(m.values) && m.values.length ? m.values[m.values.length - 1].value : null;
      if (v && typeof v === 'object') {
        let s = 0, n = 0;
        for (const x of Object.values(v)) if (zahl(x) !== null) { s += zahl(x); n++; }
        if (n) w.reactions = s;
        if (zahl(v.like) !== null) w.reactions_like = zahl(v.like);
      }
      continue;
    }
    const x = kennzahl(m);
    if (x === null) continue;
    if (m.name === 'post_media_view') w.views = x;
    else if (m.name === 'post_total_media_view_unique') w.reach = x;
    else if (m.name === 'post_clicks') w.clicks = x;
  }
  return w;
}
function erfolg(st, req, body) {
  if (req.art === 'konto') {
    kontoWert(st, 'followers_count', body.followers_count !== undefined ? body.followers_count : body.fan_count);
    if (typeof body.name === 'string' && body.name.trim()) st.d.konto_name = body.name.trim();
  } else if (req.art === 'tag') {
    const m = (Array.isArray(body.data) ? body.data : []).find(x => x && x.name === req.metrik);
    // end_time markiert das Ende des Tages; der Wert gehört zum Vortag (Schlussfolgerung, nicht geprüft)
    for (const v of (m && Array.isArray(m.values) ? m.values : [])) {
      if (!v || !v.end_time) continue;
      const t = tagBerlin(new Date(new Date(v.end_time).getTime() - 12 * 3600 * 1000));
      if (t) tagWert(st, t, SEITE_M[req.metrik], v.value);
    }
  } else if (req.art === 'beitraege') {
    let aelter = false;
    for (const p of (Array.isArray(body.data) ? body.data : [])) {
      if (!p || !/^[0-9_]{1,100}$/.test(String(p.id || ''))) continue;
      if (st.auffrischen) st.medien_ids.push(String(p.id));
      const t = Date.parse(p.created_time);
      if (st.seit_unix && isFinite(t) && t / 1000 < st.seit_unix) {
        aelter = true;
        // Migration 151: beim Auffrischen ältere Beiträge nur mit Bildadresse (keine Zahlen, keine Insights, kein neuer Beitrag)
        if (st.auffrischen) { const x = beitragSetzen(st, { extern_id: p.id, link: p.permalink_url, vorschau_url: bildAdresse(p.full_picture) }); if (x && !verfolgt(st, p.id)) x.nur_vorschau = true; }
        continue;
      }
      const neu = !st.d.beitraege[p.id] && !verfolgt(st, p.id);
      beitragSetzen(st, { extern_id: p.id, art: 'POST', produkt_art: p.status_type ? String(p.status_type).toUpperCase() : undefined,
        erstellt: isFinite(t) ? new Date(t).toISOString() : undefined, link: p.permalink_url, vorschau_url: bildAdresse(p.full_picture), text_inhalt: p.message });
      if (neu) beitragInsights(st, p.id);
    }
    const next = body.paging && body.paging.next ? weiterParameter(body.paging.next) : null;
    if (st.auffrischen) {
      // Prüfung 2j (B1): vollständig nur, wenn kein next mehr kommt; leere Seite mit next → weiterblättern (bis zur Seitengrenze);
      // Antwort ohne Liste data (abgeschnitten) → nicht vollständig
      if (!Array.isArray(body.data)) st.medien_unklar = true;
      if (next && Array.isArray(body.data) && req.seite < MAX_SEITEN_AUFFRISCHEN) st.offen.push({ art: 'beitraege', seite: req.seite + 1, pfad: req.pfad, query: Object.assign({}, req.query, next) });
      else st.medien_komplett = !next && !st.medien_unklar;
    } else if (next && !aelter && st.seit_unix && req.seite < MAX_SEITEN) {
      st.offen.push({ art: 'beitraege', seite: req.seite + 1, pfad: req.pfad, query: Object.assign({}, req.query, next) });
    }
  } else if (req.art === 'beitrag') {
    const w = postWerte(body);
    if (Object.keys(w).length) beitragSetzen(st, { extern_id: req.extern_id, werte: w });
  }
}
// Fehler 100 (Kennzahl entfallen bzw. ungültig): Seiten-Kennzahl überspringen mit Hinweis; Beitrag: Kennzahlen einzeln abfragen
function sonstFehler(st, req, f) {
  // Migration 151: Fehler beim Blättern der Beitragsliste → Liste gilt nicht als vollständig
  if (req.art === 'beitraege') { st.medien_fehler = true; st.medien_komplett = false; }
  if (f.code !== '100') return false;
  if (req.art === 'tag') { hinweis(st, '100', 'Facebook liefert die Kennzahl ' + req.metrik + ' nicht mehr. Die übrigen Zahlen sind gespeichert.'); return true; }
  if (req.art === 'beitrag' && !req.einzeln) {
    for (const m of POST_M) st.offen.push({ art: 'beitrag', einzeln: true, extern_id: req.extern_id, pfad: req.pfad, query: { metric: m } });
    return true;
  }
  return req.art === 'beitrag';
}

// ---- Gemeinsamer Teil "Abruf steuern" für Facebook, Threads, YouTube, Pinterest, TikTok (Stefan 18.10.2026, Vertrag Migration 48, 3.4) ----
// Muster wie TALENTS 1: eine Anfrage-Warteschlange je Kanal; der Zustand st reist im ersten Eintrag mit.
// Eingang A: Startzeile (start === true aus "Je Kanal" bzw. "Zugang erneuern?", oder Feld start aus "Zugang speichern").
// Eingang B: Antworten von "Plattform-Abruf" (gleiche Reihenfolge wie "Anfrage").
// Ausgabe: aktion 'abruf' (url, methode, body_text) oder aktion 'ende' (daten zum Speichern, fehler).
// Zugangsschlüssel kommen hier nie vor: "Plattform-Abruf" setzt die Kopfzeile Authorization selbst.
// Vor diesem Teil steht das Plattform-Modul (PL, beginnen, erfolg, sonstFehler, fehlerPlattform, ABGELAUFEN_BEI_TOKEN).
const BUENDEL = 10;
const MAX_ABRUFE = 1500;
const MUSTER = /(ya29\.|1\/\/0|act\.|rft\.|pina_|pinr|EAA|IGAA|IGQV|TH[A-Z]{2})[A-Za-z0-9!*._|-]{16,}/g;

function kopie(x) { return JSON.parse(JSON.stringify(x)); }
function zahl(v) {
  if (typeof v === 'number' && isFinite(v)) return v;
  if (typeof v === 'string' && /^-?[0-9]{1,15}(\.[0-9]{1,6})?$/.test(v.trim())) return Number(v.trim());
  return null;
}
function kurz(t, n) {
  return String(t == null ? '' : t).replace(MUSTER, '***').replace(/(access_token|refresh_token|client_secret|client_key)=[^&\s"']+/gi, '$1=***')
    .replace(/\s+/g, ' ').trim().slice(0, n || 200);
}
// Beitragstext (eigener Beitrag): nichts, was die Schutzprüfung der Datenbank als Schlüssel ansieht
function textSauber(t) {
  if (typeof t !== 'string' || !t.trim()) return undefined;
  return t.replace(MUSTER, '***').replace(/(access|refresh|client|fb_exchange|th_exchange)_(token|secret|key)/gi, '$1 $2').slice(0, 5000);
}
function httpsAdresse(u) {
  if (typeof u !== 'string' || !/^https:\/\/\S+$/.test(u) || u.length > 2000) return undefined;
  if (/access_token|refresh_token|client_secret|client_key/i.test(u) || /(ya29\.|EAA|act\.|pina_)[A-Za-z0-9_-]{20,}/.test(u)) return undefined;
  // Migration 151 (Prüfung 2j, H5): dieselben Muster wie die Schutzprüfung der Datenbank (talents_plattform_abruf_speichern) – eine solche
  // Adresse wird weggelassen, statt das Speichern des ganzen Datensatzes zu verhindern
  if (/fb_exchange_token|th_exchange_token/i.test(u) || /(ya29[.][A-Za-z0-9_-]{20,}|1\/\/0[A-Za-z0-9_-]{20,}|act[.][A-Za-z0-9!*._-]{20,}|rft[.][A-Za-z0-9!*._-]{20,}|pina_[A-Za-z0-9]{20,}|pinr[A-Za-z0-9._-]{20,}|EAA[A-Za-z0-9]{30,})/.test(u)) return undefined;
  return u;
}
// Migration 151 (Punkt 2j): Adresse eines Bildes (https, ohne Schlüssel), nie eine Video- oder Stream-Adresse
function bildAdresse(u) {
  const x = httpsAdresse(u);
  return x && !/\.(mp4|m4v|mov|webm|mkv|avi|wmv|flv|3gp|m3u8|mpd|ts)$/i.test(x.split(/[?#]/)[0]) ? x : undefined;
}
function enc(v) { return encodeURIComponent(String(v)); }
function adresse(st, req) {
  const q = req.query || {};
  const teile = Object.keys(q).filter(k => q[k] !== undefined && q[k] !== null && q[k] !== '').map(k => enc(k) + '=' + enc(q[k]));
  return st[req.basis || 'api'] + '/' + req.pfad + (teile.length ? '?' + teile.join('&') : '');
}
// paging.next (Meta): nur die Parameter übernehmen, nie access_token
function weiterParameter(next) {
  if (typeof next !== 'string' || next.indexOf('?') < 0) return null;
  const q = {};
  for (const teil of next.slice(next.indexOf('?') + 1).split('#')[0].split('&')) {
    if (!teil) continue;
    const i = teil.indexOf('=');
    let k, v;
    try {
      k = decodeURIComponent((i < 0 ? teil : teil.slice(0, i)).replace(/\+/g, ' '));
      v = decodeURIComponent((i < 0 ? '' : teil.slice(i + 1)).replace(/\+/g, ' '));
    } catch (e) { continue; }
    if (/^(access_token|appsecret_proof|client_secret|input_token)$/i.test(k)) continue;
    q[k] = v;
  }
