function tagMinus(tag, n) {
  const t = new Date(tag + 'T12:00:00Z'); t.setUTCDate(t.getUTCDate() - n); return t.toISOString().slice(0, 10);
}
function tagWert(st, tag, schluessel, wert) {
  if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(tag)) || zahl(wert) === null) return;
  if (tag < st.von || tag > st.bis) return;
  (st.d.tage[tag] = st.d.tage[tag] || {})[schluessel] = zahl(wert);
}
function kontoWert(st, schluessel, wert) { if (zahl(wert) !== null) st.d.konto[schluessel] = zahl(wert); }
function beitragSetzen(st, b) {
  if (!b || !/^[A-Za-z0-9_.:-]{1,100}$/.test(String(b.extern_id || ''))) return null;
  const alt = st.d.beitraege[b.extern_id] || { extern_id: String(b.extern_id), werte: {} };
  for (const f of ['art', 'produkt_art', 'erstellt']) if (b[f] !== undefined && b[f] !== null && b[f] !== '') alt[f] = String(b[f]).slice(0, 60);
  if (httpsAdresse(b.link)) alt.link = httpsAdresse(b.link);
  if (httpsAdresse(b.vorschau_url)) alt.vorschau_url = httpsAdresse(b.vorschau_url);
  if (textSauber(b.text_inhalt)) alt.text_inhalt = textSauber(b.text_inhalt);
  for (const [k, v] of Object.entries(b.werte || {})) if (zahl(v) !== null && /^[a-z0-9_]{1,60}$/.test(k)) alt.werte[k] = zahl(v);
  st.d.beitraege[alt.extern_id] = alt;
  return alt;
}
function verfolgt(st, id) { return st.verfolgt.indexOf(String(id)) >= 0; }
function zielgruppe(st, aufteilung, gruppe, werte) {
  const w = {};
  for (const [k, v] of Object.entries(werte || {})) if (zahl(v) !== null && String(k).length <= 80) w[String(k)] = zahl(v);
  if (Object.keys(w).length) st.d.zielgruppen[gruppe + ':' + aufteilung] = w;
}
function daten(st) {
  const d = st.d;
  const tage = Object.keys(d.tage).sort().map(tag => ({ tag, werte: d.tage[tag] }));
  const beitraege = Object.values(d.beitraege);
